using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");
            entity.HasIndex(p => p.Sku);

            // EF Core 9 breaking change: discriminator property renamed from
            // "Discriminator" to "$type". Preserve the old name so existing
            // 500K documents and direct SQL queries (c.Discriminator) keep working.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 breaking change: id values no longer include the
            // discriminator prefix. Old format was "Product|123", new default
            // is just the key value. Preserve the old format for compatibility
            // with existing documents.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id).ToJsonProperty("id");
            entity.UseETagConcurrency();
        });

        // Preserve the EF Core 8 id format ("Product|123") so EF can read
        // existing documents without a data migration.
        modelBuilder.Entity<Product>().Property(p => p.Id)
            .HasValueGenerator<LegacyCosmosIdGenerator>();
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // EF Core 9 breaking change: sync APIs (ToList, First, Single, etc.)
        // were removed for the Cosmos provider. All queries must be async.
    }
}

